using GraphApi.Models.ENC.TiposPregunta;namespace GraphApi.Services.ENC.TiposPregunta{    /// <summary>    /// Define las operaciones de negocio y persistencia para TiposPreguntas.    /// </summary>    public interface ITiposPreguntaService    {        /// <summary>        /// Obtiene la lista de TiposPreguntas con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadTiposPregunta>> GetTiposPreguntas(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de TiposPreguntas con filtros opcionales.        /// </summary>        /// <param name="tipoPreguntaID">Filtro opcional para TipoPreguntaID.</param>        /// <param name="tipoPregunta">Filtro opcional para TipoPregunta.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetTiposPreguntasDynamic(            int? tipoPreguntaID,            string? tipoPregunta,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo TiposPregunta.        /// </summary>        /// <param name="objInput">Datos para crear el TiposPregunta.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadTiposPregunta> CreateTiposPregunta(            clCreateTiposPregunta objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un TiposPregunta.        /// </summary>        /// <param name="objInput">Datos para actualizar el TiposPregunta, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadTiposPregunta?> UpdateTiposPregunta(            clUpdateTiposPregunta objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un TiposPregunta por su ID.        /// </summary>        /// <param name="nTiposPreguntaID">ID del TiposPregunta a eliminar.</param>        Task<bool> DeleteTiposPregunta(int nTiposPreguntaID);    }}